<# Aktualisiert eine lokale Codex-CLI unter %USERPROFILE%\.local\bin, sofern sie dort liegt. #>
[CmdletBinding()] param()
$ErrorActionPreference = 'Stop'; $ziel = Join-Path $env:USERPROFILE '.local\bin\codex.exe'; $api = 'https://api.github.com/repos/openai/codex/releases/latest'
if (-not (Test-Path $ziel)) { if (Get-Command codex -ErrorAction SilentlyContinue) { Write-Output "OK codex liegt unter $((Get-Command codex).Source), nicht unter %USERPROFILE%\.local\bin." } else { Write-Output 'OK codex ist nicht eingerichtet, nichts zu tun.' }; exit 0 }
try { $release = Invoke-RestMethod $api -Headers @{ 'User-Agent'='maschinenraum' }; $asset = $release.assets | Where-Object { $_.name -match 'x86_64-pc-windows-msvc\.zip$' } | Select-Object -First 1; if (-not $asset) { throw 'Windows-Archiv in der neuesten Veröffentlichung nicht gefunden' }; $tmp = Join-Path ([IO.Path]::GetTempPath()) "codex-$([guid]::NewGuid())"; New-Item -ItemType Directory $tmp | Out-Null; Invoke-WebRequest $asset.browser_download_url -OutFile "$tmp\codex.zip"; Expand-Archive "$tmp\codex.zip" $tmp -Force; $neu = Get-ChildItem $tmp -Recurse -Filter 'codex.exe' | Select-Object -First 1; if (-not $neu) { throw 'im Archiv keine Programmdatei gefunden' }; & $neu.FullName --version | Out-Null; Copy-Item $ziel "$ziel.vorher" -Force; Move-Item $neu.FullName $ziel -Force; Write-Output "OK codex auf $($release.tag_name) aktualisiert (alte Fassung: $ziel.vorher)" } catch { Write-Error "FEHLER codex: $($_.Exception.Message)"; exit 1 } finally { if ($tmp) { Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue } }
